/** Scroll-driven product explanation. Pure progress math stays separate from DOM effects.
 * Sections remain real readable HTML; reduced motion and narrow screens use a static layout.
 */
export function assemblyProgress(top,height,viewport){return Math.max(0,Math.min(1,-top/Math.max(1,height-viewport)))}
export function assemblyPose(progress,index){const arrival=Math.max(0,Math.min(1,(progress-index*.14)/.55));const eased=1-(1-arrival)**3;return {x:(1-eased)*[70,-75,50][index],y:(1-eased)*[-55,10,45][index],rotation:(1-eased)*[-12,10,-8][index],depth:(1-eased)*[100,60,80][index]}}
export function assembly(){return `<section class="assembly" aria-label="个人空间的功能组装"><div class="assembly-sticky"><div class="assembly-copy"><span class="eyebrow">个人空间 / 交互设计原型</span><h2>把分散的表达，<br>组装成<span>自己的空间。</span></h2><p class="assembly-intro">一篇文字建立认识，一部作品提供依据，<br>一份清楚的介绍，让交流有了下一步。</p><ol class="assembly-steps"><li><b>被看见</b><span>文字与专题，让读者找到关心的问题。</span></li><li><b>被理解</b><span>作品与过程，让读者看懂你的思考。</span></li><li><b>有下一步</b><span>商品说明与联系入口，承接真实需求。</span></li></ol><p class="assembly-hint">向下滚动，看看它们如何组成一个网站。</p><a class="text-link" href="#/project/website">阅读完整项目说明 ↗</a><a class="assembly-skip" href="#/projects" data-section="project-directory">跳过动效，查看作品目录 ↓</a></div><div class="assembly-model"><div class="assembly-shell"><div class="assembly-browser"><i></i><i></i><i></i><span>LINGBO / PERSONAL SPACE</span></div><div class="assembly-header"><strong>黄凌波</strong><span>文字　作品　小店</span></div><div class="assembly-module module-writing"><small>文字 / IDEAS</small><h3>先做小，<br>再做长。</h3><p>从一个具体的问题开始。</p><div class="assembly-lines"><i></i><i></i><i></i></div></div><div class="assembly-module module-project"><small>作品 / PRACTICE</small><div class="assembly-diagram"><i></i><i></i><i></i></div><h3>让想法，有迹可循。</h3><p>目标、过程与选择。</p></div><div class="assembly-module module-shop"><small>小店 / NEXT STEP</small><h3>先了解，再决定。</h3><p>目录 · 试读 · 交付说明</p><span>查看内容与联系入口 ↗</span></div><div class="assembly-caption">DESIGN PROTOTYPE · 示例界面，非真实业务成果</div></div></div><div class="assembly-meter" aria-hidden="true"><i></i></div></div></section>`}
export function mountAssembly(root){const region=root.querySelector('.assembly');if(!region)return()=>{};const media=matchMedia('(max-width: 900px), (prefers-reduced-motion: reduce)'),control=new AbortController();let frame=0;const panels=[...region.querySelectorAll('.assembly-module')],steps=[...region.querySelectorAll('.assembly-steps li')];function draw(){frame=0;const p=media.matches?1:assemblyProgress(region.getBoundingClientRect().top,region.offsetHeight,region.querySelector('.assembly-sticky').offsetHeight);panels.forEach((el,i)=>{const pose=assemblyPose(p,i);el.style.transform=media.matches?'none':`translate3d(${pose.x}px,${pose.y}px,${pose.depth}px) rotateZ(${pose.rotation}deg)`});region.querySelector('.assembly-shell').style.transform=media.matches?'none':`rotateX(${(1-p)*12}deg) rotateY(${(1-p)*-16}deg) rotateZ(${(1-p)*4}deg)`;steps.forEach((el,i)=>el.classList.toggle('is-lit',p>=i*.28));region.querySelector('.assembly-meter i').style.transform=`scaleX(${p})`;}function schedule(){if(!frame)frame=requestAnimationFrame(draw)}window.addEventListener('scroll',schedule,{passive:true,signal:control.signal});window.addEventListener('resize',schedule,{signal:control.signal});media.addEventListener('change',schedule,{signal:control.signal});draw();return()=>{control.abort();cancelAnimationFrame(frame)}}
